select pa.id, pad.id as purchaseApplicationDetailId, pa.code, pad.is_urgent as isUrgent, pa.approve_status as approveStatus, pa.is_first_mass_product as isFirstMassProduct, pad.create_po_type as createPoType, pad.sku_id as skuId, pad.sku_no as skuNo, pad.product_name as productName, pad.variant_property as variantProperty, pad.plan_delivery_date as planDeliveryDate, pad.apply_qty as applyQty, pad.receive_qty as receiveQty, pad.stock_in_qty as stockInQty, pad.dest_warehouse_name as destWarehouseName, pad.remark, pa.approve_user_name as approveUserName, pa.approve_time as approveTime, pa.create_user_name as createUserName, pa.create_time as createTime, s.id as supplierId, s.name as supplierName, pad.close_reason as closeReason, pa.source_id, pa.source_code, pa.source_type from purchase_application pa inner join purchase_application_detail pad on pa.id = pad.purchase_application_id and pad.is_deleted = false left join supplier s on pad.supplier_id = s.id and s.is_deleted = false where ${params.sqlMap.default} and pa.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
pa.id desc , pad.id asc

